import type { ViewTransitionProps } from 'react'

/**
 * Directional page slides. `<Link transitionTypes>` tags each navigation as
 * forward or back, and these maps turn that tag into the matching animation.
 *
 * Untyped transitions (browser back/forward, `router.refresh()`, Suspense
 * reveals) fall through to `none` so they don't pick up a direction they
 * don't have. Spread onto the outermost element of a `page.tsx` — layouts
 * persist across navigation, so enter/exit never fire there.
 */
export const navSlide: Pick<ViewTransitionProps, 'enter' | 'exit' | 'default'> =
  {
    enter: {
      'nav-forward': 'nav-forward',
      'nav-back': 'nav-back',
      default: 'none',
    },
    exit: {
      'nav-forward': 'nav-forward',
      'nav-back': 'nav-back',
      default: 'none',
    },
    default: 'none',
  }

/**
 * Suspense reveal, skeleton half: the placeholder yields downward.
 *
 * Both halves opt out during a directional navigation. When a destination
 * renders without suspending, the page slide and the reveal would otherwise
 * fire in the same transition and animate the same content twice.
 */
export const revealFallback: Pick<ViewTransitionProps, 'exit' | 'default'> = {
  exit: { 'nav-forward': 'none', 'nav-back': 'none', default: 'slide-down' },
  default: 'none',
}

/** Suspense reveal, content half: the real thing arrives upward. */
export const revealContent: Pick<ViewTransitionProps, 'enter' | 'default'> = {
  enter: { 'nav-forward': 'none', 'nav-back': 'none', default: 'slide-up' },
  default: 'none',
}

/**
 * Shared element pairing for a product image. Both the grid thumbnail and the
 * detail hero call this, so the two `name`s can't drift apart.
 *
 * `default: 'none'` keeps the image out of unrelated transitions; `share`
 * has to stay explicit alongside it or the pair stops morphing.
 */
export function morphProductImage(
  slug: string,
): Pick<ViewTransitionProps, 'name' | 'share' | 'default'> {
  return { name: `product-image-${slug}`, share: 'morph', default: 'none' }
}

