@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ---------------------------------------------------------------------------
   View transitions

   Timing is asymmetric on purpose: old content leaves quickly so it stops
   competing for attention, new content arrives more gently so there's time to
   register it. The enter fade is delayed by the exit duration so the two never
   overlap.
   --------------------------------------------------------------------------- */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* The transition overlay swallows pointer events by default, which drops any
   click landing mid-animation. Pass them through to the live page. */
::view-transition {
  pointer-events: none;
}

/* Shared element: grid thumbnail <-> detail hero.
   400ms is slow enough to read as one object moving, fast enough to feel
   direct. The blur keyframe hides pixel interpolation artifacts mid-flight. */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}

/* Suspense reveal: the skeleton yields downward, content arrives upward. */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}
::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

/* Directional navigation: forward travels left, back travels right. 60px is
   enough to signal direction without making the eye chase the content. */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide-x reverse;
}
::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide-x;
}

::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide-x reverse;
}
::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide-x;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes fade-opacity {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes slide-x {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* Reduced motion: keep the opacity crossfades, drop everything positional.
   Movement across the viewport is the main motion-sensitivity trigger, so the
   slides lose their travel and blur but still fade, and the morph snaps its
   geometry while the pair crossfades. Content never swaps without any
   visual link, and nothing moves. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(.slide-down),
  ::view-transition-old(.nav-forward),
  ::view-transition-old(.nav-back) {
    animation: var(--duration-exit) ease-out both fade-opacity reverse;
  }

  ::view-transition-new(.slide-up),
  ::view-transition-new(.nav-forward),
  ::view-transition-new(.nav-back) {
    animation: var(--duration-enter) ease-in var(--duration-exit) both
      fade-opacity;
  }

  /* The group animation is what interpolates size and position. */
  ::view-transition-group(.morph) {
    animation-duration: 0s;
  }
  ::view-transition-image-pair(.morph) {
    animation-name: none;
  }

  /* Also drop the pre-existing skeleton pulse: it's an indefinite loop, and
     the grey blocks still read as loading without it. */
  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

